WITH unpacked AS (SELECT id, created_at, items, attributes, ship_to.city AS ship_city, ship_to.country AS ship_country, EXISTS(items, item -> item.price > 100) AS has_premium_item, SIZE(attributes) AS num_attributes, ARRAY_CONTAINS(coupon_codes, 'VIP') AS used_vip FROM carts) SELECT CASE WHEN num_attributes >= 63 THEN 'HIGH' ELSE 'LOW' END AS num_attributes_tier, DATE_TRUNC('DAY', created_at) AS activity_day, MAX(num_attributes) AS max_num_attributes, COUNT(*) FILTER (WHERE ship_country = 'DE') AS de_rows FROM unpacked GROUP BY 1, 2 HAVING de_rows > 1 ORDER BY num_attributes_tier
